371	// retiredMechanisms reports, in a migrated view's file, every retired
372	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
373	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
374	// imports it): the router's one tick animates every row.
375	// rel is the file's path relative to internal/; it keys declaredGlyphConstants.
376	// RenderedFrame (a method of the viewport frame) is allowed.
377	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
378		var out []finding
379		report := func(pos token.Pos, what string) {
380			out = append(out, finding{Pos: fset.Position(pos), What: what})
381		}
382		tea := bubbleTeaName(file)
383		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
384		// reportTick flags any reference to bubbletea's Tick / Every, called or not
385		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`).
386		reportTick := func(pos token.Pos, name string) {
387			if name == "Tick" || name == "Every" {
388				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
389			}
390		}
391		isFrame := func(name string) bool {
392			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
393		}
394		visit := func() func(ast.Node) bool {
395			return func(n ast.Node) bool {
396				switch x := n.(type) {
397				case *ast.CallExpr:
398					sel, ok := x.Fun.(*ast.SelectorExpr)
399					if !ok {
400						break
401					}
402					if sel.Sel.Name == "AdvanceSpinner" {
403						report(x.Pos(), "call to AdvanceSpinner")
404					}
405				case *ast.KeyValueExpr:
406					if id, ok := x.Key.(*ast.Ident); ok {
407						if id.Name == "StatusColumn" {
408							report(id.Pos(), "StatusColumn: key")
409						}
410						if isFrame(id.Name) {
411							report(id.Pos(), "frame field "+id.Name+": set")
412						}
413					}
414				case *ast.Field:
415					for _, id := range x.Names {
416						if isFrame(id.Name) {
417							report(id.Pos(), "frame field "+id.Name)
418						}
419					}
420				case *ast.Ident:
421					// Dot import: a bare Tick / Every that no declaration in the file binds.
422					if tea == "." && x.Obj == nil && !selectors[x] {
423						reportTick(x.Pos(), x.Name)
424					}
425				case *ast.SelectorExpr:
426					selectors[x.Sel] = true
427					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
428						reportTick(x.Pos(), x.Sel.Name)
429					}
430					if isFrame(x.Sel.Name) {
431						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
432					}
433				case *ast.BasicLit:
434					if x.Kind == token.STRING || x.Kind == token.CHAR {
435						s, err := strconv.Unquote(x.Value)
436						if x.Kind == token.CHAR {
437							var q rune
438							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
439							s = string(q)
440						}
441						if err == nil && strings.ContainsAny(s, activityGlyphs) {
442							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
443						}
444					}
445				}
446				return true
447			}
448		}
449		for _, decl := range file.Decls {
450			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
451				for _, spec := range gd.Specs {
452					if isDeclaredGlyphConstant(rel, spec) {
453						continue
454					}
455					ast.Inspect(spec, visit())
456				}
457				continue
458			}
459			ast.Inspect(decl, visit())
460		}
461		return out
462	}
463	
464	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
465	// declaredGlyphConstants for the file rel.
466	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
467		vs, ok := spec.(*ast.ValueSpec)
468		if !ok || len(vs.Names) == 0 {
469			return false
470		}
471		for _, id := range vs.Names {
472			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
473				return false
474			}
475		}
476		return true
477	}
