func blinkRouter(t *testing.T, wants bool) (*App, *blinkView, *[]time.Duration) {
	t.Helper()
	got := stubAnimationEvery(t, time.UnixMilli(1000))
	v := &blinkView{wants: wants}
	a := router(t, v)
	a.anim.blinkOn = true
	return a, v, got
}

func startBlinkChain(t *testing.T, a *App) {
	t.Helper()
	if a.ensureTick() == nil {
		t.Fatal("a view that wants to blink got no animation chain")
	}
}

func tickAt(a *App, ms int64) tea.Cmd {
	_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(ms)})
	return cmd
}

func lastFrame(t *testing.T, v *blinkView) jobs.FrameMsg {
	t.Helper()
	frames := framesSeen(&v.fakeView)
	if len(frames) == 0 {
		t.Fatal("the view was never handed a FrameMsg")
	}
	return frames[len(frames)-1]
}

// Criterion 1: every row reads the phase of the tick.
func TestTheFrameOnlyMovesWhileWorkRuns(t *testing.T) {
	a, _, _ := blinkRouter(t, true)
	startBlinkChain(t, a)
	before := a.animationFrame()
	for ms := int64(1000); ms <= 3000; ms += 500 {
		tickAt(a, ms)
	}
	if a.animationFrame() != before {
		t.Error("blink-only ticks advanced the spinner frame")
	}
}

// Criterion 5: static motion pins the phase on and starts no chain for pastilles.
func TestStaticMotionNeverStartsAChainForIndicators(t *testing.T) {
	a, _, got := blinkRouter(t, true)
	a.anim.blinkOn = false

	a.setMotionStatic(true)

	if !a.anim.blinkOn {
		t.Error("setMotionStatic(true) did not pin the phase on")
	}
	if a.ensureTick() != nil {
		t.Error("static motion started a chain for a blink")
	}
	a.Update(testutil.Key("down"))
	if len(*got) != 0 {
		t.Errorf("static motion recorded intervals %v", *got)
	}
}

// Criterion 5: a running spinner still ticks at 100 ms, with the phase pinned on.
func TestStaticMotionPinsThePhaseOn(t *testing.T) {
	a, v, got := blinkRouter(t, true)
	a.setMotionStatic(true)
	a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
	if len(*got) == 0 || (*got)[len(*got)-1] != animationFastInterval {
		t.Fatalf("static motion with a run: intervals %v, want %v", *got, animationFastInterval)
	}
	for _, ms := range []int64{1500, 2500} {
		tickAt(a, ms)
		if !lastFrame(t, v).Blink {
			t.Errorf("tick at %d ms: Blink = false under static motion", ms)
		}
	}
}

// Criterion 6: the router asks the view after the very Update that changed it.
	}
}

// D5: a sync failure on the same path is not a scan failure for :sec.
func TestWsSyncFailureIsInvisibleToSec(t *testing.T) {
	a, repo := wsRouter(t)
	openWorkspaces(t, a)
	a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindSync, command.ViewWorkspaces, "", "ws", repo)})
	a.Update(workspaces.WorkspaceSyncCompleteMsg{RepoPath: repo, Error: errors.New("boom")})

	if _, ok := jobs.FailureFor(a.jobs.Failures(), jobs.KindSync, repo, "default"); !ok {
		t.Fatal("the sync failure was not remembered at all")
	}
	if got := jobs.FailuresOn(a.jobs.Failures(), "default", repo, jobs.KindScan); len(got) != 0 {
		t.Errorf("a sync failure is visible to :sec through KindScan: %+v", got)
	}
}

// seedWorkspacesFooter puts ws on screen with a running scan on its selected
// row, for the activity guard.
func seedWorkspacesFooter(t *testing.T, a *App) indicator.State {
	t.Helper()
	dir := t.TempDir()
	repo := filepath.Join(dir, "api")
	if err := os.MkdirAll(filepath.Join(repo, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	a.config.App.WorkspacesDir = dir
	a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", "ws", repo)})
	snap := a.jobs.Snapshot()
	if len(snap) != 1 || !a.jobs.Advance(snap[0].ID, repo, jobs.ItemRunning, "") {
		t.Fatalf("the seed could not put the scan in the running state: %+v", snap)
	}
	openWorkspaces(t, a)
	return indicator.Running
}
