// The router's blink phase feeds the footer dot when the view has no chain of
// its own running; the rendered frame no longer reaches the footer.
func TestAFrameStillFeedsTheFooterDotWhenTheViewHasNoChain(t *testing.T) {
	m := inventoryModel(t, inventoryFixtures()...)
	m = withJobs(t, m, scanningRun("nexus/api:1.4"))
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "FOOTERFRAME", Blink: false})

	footer := m.RenderFooter(120)
	if strings.Contains(footer, "FOOTERFRAME") {
		t.Error("the router's rendered frame reaches the footer")
	}
	if !strings.Contains(footer, indicator.Glyph(indicator.Running, false)) {
		t.Skip("the footer shows no dot for this state; the table side is asserted above")
	}
}
	if !m.table.BlinkPhase() {
		t.Error("Blink=true did not turn the phase back on")
	}
	after := m.table.Items()
	if len(before) == 0 || len(before) != len(after) || &before[0] != &after[0] {
		t.Error("a frame rebuilt the rows; the phase is read at render")
	}
}

func TestAFrameStillFeedsTheFooterDot(t *testing.T) {
	m := withSnapshot(t, loadedModel(t), []jobs.Run{runningRun(jobs.KindScan, indRepo)}, nil)
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "FOOTERFRAME", Blink: false})
	if strings.Contains(m.Render(), "ZZ") {
		t.Error("the bare frame still reaches the table")
	}
	if strings.Contains(m.RenderFooter(120), "FOOTERFRAME") {
		t.Error("the router's rendered frame reaches the footer; it takes the blink phase only")
	}
	if !strings.Contains(m.RenderFooter(120), indicator.Glyph(indicator.Running, false)) {
		t.Skip("footer shows no dot for this state; only the table side is asserted")
	}
}

func TestTheModelHoldsNoRowSpinnerFrame(t *testing.T) {
	if _, ok := reflect.TypeOf(Model{}).FieldByName("jobFrame"); ok {
		t.Error("Model still carries jobFrame; the phase lives in the table")
	}
}

func TestTheTableFillsTheViewportAt60Columns(t *testing.T) {
	m := feed(t, loadedModel(t), tea.WindowSizeMsg{Width: 60, Height: 30})
	if got := m.table.RenderedWidth(); got != 58 {
		t.Errorf("RenderedWidth = %d, want 58", got)
	}
}

func TestJobsDotFollowsTheBlinkPhase(t *testing.T) {
	m := idleRowDuringBatch(t)
	on := plainInfoLine(feed(t, m, jobs.FrameMsg{Blink: true}), 200)
	off := plainInfoLine(feed(t, m, jobs.FrameMsg{Blink: false}), 200)
	if !strings.Contains(off, "○") || strings.Contains(off, "●") {
		t.Errorf("Blink=false must give the hollow dot only, got %q", off)
	}
	if strings.Index(on, "Scanning") != strings.Index(off, "Scanning") {
		t.Errorf("the text moved between phases: %q vs %q", on, off)
	}
}

// Load wins over jobs: the inventory load keeps the view's own spinner frame and
// no dot, and a router frame does not replace it.
func TestTheInventoryLoadKeepsItsOwnSpinnerAndNoDot(t *testing.T) {
	m := footerModel(t, []jobs.Run{batch()}, nil)
	m = selectTarget(t, m, ftOther) // idle row: no glyph detail
	m.inventoryLoading = true
	m.footer.SetSpinnerFrame("⠹") // the view's own spinner.TickMsg handler
	if st := m.inventoryStatus(); !st.Spinner || st.Activity {
		t.Fatalf("while loading: Spinner=%v Activity=%v, want Spinner only", st.Spinner, st.Activity)
	}
	m = feed(t, m, jobs.FrameMsg{Blink: true, Frame: "ZZ", RenderedFrame: "FOOTERFRAME"})
	got := infoLine(m, 200)
	if !strings.Contains(got, "⠹") || strings.Contains(got, "FOOTERFRAME") {
		t.Errorf("the own spinner must stay and the router frame stay out: %q", ansi.Strip(got))
	}
	if strings.ContainsAny(ansi.Strip(got), "●○") {
		t.Errorf("a dot beside the load spinner: %q", ansi.Strip(got))
	}
}

func TestNoUnfinishedRunMeansNoFooterDot(t *testing.T) {
	m := footerModel(t, nil, nil)
	m.inventoryLoading = false
	m = feed(t, m, jobs.FrameMsg{Blink: false})
	if got := plainInfoLine(m, 200); strings.ContainsAny(got, "●○") {
		t.Errorf("a dot without a running job: %q", got)
	}
}

func TestAFooterErrorHidesTheDotWhileAScanRuns(t *testing.T) {
	m := feed(t, idleRowDuringBatch(t), jobs.FrameMsg{Blink: true})
	m.footer.Error("it broke")
	got := plainInfoLine(m, 200)
	if !strings.Contains(got, "it broke") || strings.ContainsAny(got, "●○") {
		t.Errorf("want the error and no dot, got %q", got)
	}
}

