	m.inventoryLoading = false
	m = feed(t, selectTarget(t, m, ftRepo), jobs.FrameMsg{Blink: true})
	if got := plainInfoLine(m, 200); strings.Count(got, "●") != 1 {
		t.Errorf("want exactly one ●, got %q", got)
	}
